package eu.karelhovorka.zpevnik.formatter

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * html/before: rendered by the old parser (chords 351afad), frozen, never regenerated by tests.
 *   To add songs: check out 351afad in a worktree, copy HtmlSnapshots.kt (only) and the songs there,
 *   and run its HtmlSnapshotWriter with HTML_SNAPSHOT_DIR pointing to html/before.
 * html/after: rendered by the current code; run with UPDATE_GOLDEN=1 after an intended change.
 * Every difference in visible text between the two must be listed in [reviewedChanges] with a reason;
 * markup may change freely (e.g. legacy is rendered from chord pairs now).
 */
class HtmlDisplayTest {

    private val htmlDir = File(HtmlSnapshots.root(), "src/jvmTest/resources/html")

    private fun read(set: String): Map<String, String> {
        val dir = File(htmlDir, set)
        return dir.walk().filter { it.isFile }.associate { it.relativeTo(dir).path to it.readText() }
    }

    @Test
    fun currentHtmlMatchesAfterSnapshots() {
        val after = File(htmlDir, "after")
        if (System.getenv("UPDATE_GOLDEN") == "1") {
            after.deleteRecursively()
            HtmlSnapshots.writeAll(after)
        }
        val expected = read("after")
        val actual = HtmlSnapshots.renderAll()
        assertEquals(expected.keys, actual.keys)
        for ((path, html) in actual) {
            assertEquals(path, expected[path], html)
        }
    }

    @Test
    fun beforeAndAfterCoverSameSnapshots() {
        assertTrue(read("before").isNotEmpty())
        assertEquals(read("before").keys, read("after").keys)
    }

    @Test
    fun everyDisplayChangeIsReviewed() {
        val before = read("before").mapValues { visibleText(it.value) }
        val after = read("after").mapValues { visibleText(it.value) }
        val changed = before.keys.filter { before[it] != after[it] }.toSortedSet()
        assertEquals(reviewedChanges.keys.toSortedSet(), changed)
    }

    companion object {
        /** Text the reader sees: no head, no tags, entities decoded, no trailing spaces or carriage returns. */
        fun visibleText(html: String): String = html
            .replace(Regex("(?s)<head>.*?</head>"), "")
            // like HTML: "<3" in lyrics is text, a tag starts with a letter
            .replace(Regex("(?s)<!--.*?-->|</?[A-Za-z][^>]*>"), "")
            .replace("&nbsp;", "\u00a0").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&amp;", "&")
            .replace("\r", "")
            .lines().joinToString("\n") { it.trimEnd() }

        private val withText = listOf("default", "comments", "hide-chords", "hide-identical", "transposed")
        private val all = withText + "hide-text"

        private fun changed(song: String, layouts: List<String>, variants: List<String>, reason: String) =
            layouts.flatMap { layout -> variants.map { "$song/$layout-$it.html" to reason } }

        private val sectioned = listOf("inline", "upper")
        private val allLayouts = listOf("legacy", "inline", "upper")

        val reviewedChanges: Map<String, String> = listOf(
            changed(
                "accented-headers", sectioned, withText,
                "Předehra:, Sloka 1:, Refrén:, Recitál: are section headers; before, the intro chords were paired with the text 'Sloka 1:'"
            ),
            changed(
                "english-headers", sectioned, withText,
                "Verse 1:, Verse 2: are section headers; before, 'Verse 2:' was swallowed by the chorus and repeated with it"
            ),
            changed(
                "header-like-lyrics", sectioned, withText,
                "KNOWN RISK: lyric lines 'Řekni:', '2. dubna…', 'B: …' now start sections"
            ),
            changed(
                "header-with-chords", sectioned, withText,
                "'Intro: C G Am F', 'Mezihra: [Am] [F]', 'R: C G' are headers with chords; before, one block with chords as text"
            ),
            changed(
                "header-with-chords", listOf("legacy"), withText,
                "plain chords behind a header label ('Intro: C G Am F') are chord links now; 'hide chords' leaves no double spaces"
            ),
            changed(
                "invalid-and-lowercase-chords", allLayouts, all,
                "KNOWN RISK: lowercase [a], [e7] are not chords any more, shown as literal text"
            ),
            changed(
                "jazz-chords", allLayouts, all,
                "Em7b5, A7#9, G7b9, C7#5 are chords; before, shown as text, survived 'hide chords', missing in 'hide text'"
            ),
            changed("multi-chord-brackets", allLayouts, listOf("hide-chords"), "whitespace only: removing chords leaves no double spaces"),
            changed(
                "repeats", sectioned, withText,
                "TEMPORARY: trailing 2x/(2x)/x3 moved to SectionLine.repeatCount, not rendered until the new template (legacy unaffected)"
            ),
            changed(
                "same-line-headers", sectioned, withText,
                "'1. text' and 'R: text' start sections; before, the whole song was one block"
            ),
            changed(
                "tabs-and-indent", allLayouts, listOf("default", "comments", "hide-identical", "transposed"),
                "tabs count to 8-column stops, chords land on the right syllable; legacy only changes tabs to spaces"
            ),
        ).flatten().toMap()
    }
}
